1	import fs from 'node:fs';
2	import path from 'node:path';
3	import { StringDecoder } from 'node:string_decoder';
4	import { createRequire } from 'node:module';
5	import {
6	  canonicalizePath,
7	  getHomeDir,
8	  getBrainStores,
9	  getAntigravitySurfaces,
10	  getClaudeCodeProjectsDir,
11	  getCursorWorkspaceStorageDirs,
12	  getCodexSessionsDir,
13	  getGeminiCliChatsDirs,
14	  isCrossHostHarnessEnabled
15	} from './paths.mjs';
16	import { EFFORT_PROFILES, resolveEffortProfile, resolveSurfaceTag, normalizeModelId } from './constants.mjs';
17	import { stitchAntigravityCliTrajectory, stitchClaudeCodeDag } from './trajectory_stitcher.mjs';
18	import { atomicWriteFileSync } from './atomic_io.mjs';
19	import { getDatabaseSyncClass } from '../engine-node/db/probe.mjs';
