24	
25	/**
26	 * Zero-Trust Read-Only Filesystem Lock Configuration (SQLITE_OPEN_READONLY).
27	 * Never acquires write locks on active Antigravity session databases (conversations/*.db,
28	 * conversation_summaries.db) or JSONL transcript files (transcript_full.jsonl).
29	 */
30	export const SQLITE_OPEN_READONLY_OPTIONS = Object.freeze({ readOnly: true });
31	export const ZERO_TRUST_SECURITY_MANIFEST = Object.freeze({
32	  networkProfile: 'ZERO_OUTBOUND_CONNECTIONS',
33	  telemetryParsing: '100%_LOCAL_IN_MEMORY',
34	  sqliteOpenFlag: 'SQLITE_OPEN_READONLY',
35	  sqliteOptions: SQLITE_OPEN_READONLY_OPTIONS,
36	  jsonlOpenMode: 'r',
37	  requiresExternalApiKeys: false
38	});
