40	/**
41	 * Matches the host's settings-change sentence, e.g.
42	 * "The user changed setting `Model Selection` from Claude Sonnet 5.5 (Medium) to Claude Opus 5.5 (Medium). No need ..."
43	 * Values may contain dots ("5.5"), so the terminator is ". No need" (or a sentence end at block end).
44	 */
45	const SETTINGS_CHANGE_RE = /changed setting\s+`(Model Selection|Reasoning Effort|Effort)`\s+from\s+(.+?)\s+to\s+(.+?)\.\s+No need/i;
46	const SETTINGS_CHANGE_FALLBACK_RE = /changed setting\s+`?(Model Selection|Reasoning Effort|Effort)`?\s+from\s+(.+?)\s+to\s+(.+?)\.?\s*(?:<|$)/i;
47	
48	/**
49	 * Only genuine user turns carry authoritative settings-change blocks. Tool output, code views
50	 * and planner text that merely quote the tag are ignored.
51	 */
52	function isUserInputEntry(entry) {
53	  const t = String(entry?.type || '').toUpperCase();
54	  if (t) return t === 'USER_INPUT';
55	  return /^USER/i.test(String(entry?.source || ''));
56	}
57	
58	/**
59	 * Parses all <USER_SETTINGS_CHANGE> blocks in a user turn.
60	 * Returns [{ setting, from, to }] in order of appearance.
61	 */
62	export function parseSettingsChanges(rawContent = '') {
63	  const out = [];
64	  const text = String(rawContent || '');
65	  if (!text.includes('<USER_SETTINGS_CHANGE>')) return out;
66	  const blocks = text.match(/<USER_SETTINGS_CHANGE>[\s\S]*?<\/USER_SETTINGS_CHANGE>/gi) || [];
67	  for (const block of blocks) {
68	    const inner = block.replace(/<\/?USER_SETTINGS_CHANGE>/gi, '').replace(/\r?\n/g, ' ').trim();
69	    const m = inner.match(SETTINGS_CHANGE_RE) || inner.match(SETTINGS_CHANGE_FALLBACK_RE);
70	    if (m) {
71	      out.push({ setting: m[1], from: m[2].trim(), to: m[3].trim() });
72	    }
73	  }
74	  return out;
75	}
76	
77	/**
78	 * Returns the most recent `Model Selection` target from USER_INPUT settings-change blocks,
79	 * or null when the transcript never records a model switch.
80	 */
81	export function resolveModelFromTranscript(steps = []) {
82	  for (let i = (steps?.length || 0) - 1; i >= 0; i--) {
83	    const st = steps[i];
84	    if (!st || !isUserInputEntry(st)) continue;
85	    const content = String(st.content || '');
86	    if (!content.includes('<USER_SETTINGS_CHANGE>')) continue;
87	    const changes = parseSettingsChanges(content).filter(c => /model selection/i.test(c.setting));
88	    if (changes.length > 0) {
89	      const raw = changes[changes.length - 1].to;
90	      if (raw && !/^none$/i.test(raw)) return { raw, id: normalizeModelId(raw) };
91	    }
92	  }
93	  return null;
94	}
95	
96	/**
97	 * Model precedence: stdin (host) > gen_metadata.model > last USER_INPUT Model Selection > fallback.
98	 * Returns { id, raw, source: 'stdin' | 'gen_metadata' | 'transcript' | 'fallback' }.
99	 */
100	export function resolveSessionModel({ stdinData = null, genMetadata = null, steps = [], fallback = 'gemini-3.8-flash' } = {}) {
101	  const stdinModel = stdinData?.model?.id || (typeof stdinData?.model === 'string' ? stdinData.model : null) || stdinData?.modelName || null;
102	  if (stdinModel) return { id: stdinModel, raw: stdinModel, source: 'stdin' };
103	  if (genMetadata?.model) return { id: normalizeModelId(genMetadata.model), raw: genMetadata.model, source: 'gen_metadata' };
104	  const fromTranscript = resolveModelFromTranscript(steps);
105	  if (fromTranscript) return { id: fromTranscript.id, raw: fromTranscript.raw, source: 'transcript' };
106	  return { id: fallback, raw: fallback, source: 'fallback' };
107	}
108	
109	/**
110	 * Extracts model/effort metadata from a raw JSONL transcript entry if present.
111	 */
112	export function extractTurnEffortMetadata(entry) {
113	  if (!entry || typeof entry !== 'object') return null;
114	
115	  const rawContent = String(entry.content || '');
116	  let fromSpec = null;
117	  let toSpec = null;
118	  let setting = null;
119	  let modelFromSpec = null;
120	  let modelToSpec = null;
121	
122	  if (isUserInputEntry(entry) && rawContent.includes('<USER_SETTINGS_CHANGE>')) {
123	    for (const change of parseSettingsChanges(rawContent)) {
124	      if (fromSpec === null) fromSpec = change.from;
125	      toSpec = change.to;
126	      setting = change.setting;
127	      if (/model selection/i.test(change.setting)) {
128	        if (modelFromSpec === null) modelFromSpec = change.from;
129	        modelToSpec = change.to;
130	      }
131	    }
132	  }
133	
134	  const rawExplicit = entry.turnMetadata || entry.turn_metadata;
135	  const explicitMeta = rawExplicit && typeof rawExplicit === 'object' ? rawExplicit : null;
136	  const effort = explicitMeta?.effort || explicitMeta?.reasoningEffort || explicitMeta?.reasoning_effort ||
137	    entry.effort || entry.reasoning_effort || entry.reasoningEffort || null;
138	  const tier = explicitMeta?.tier || explicitMeta?.effortTier || entry.effortTier || entry.tier || null;
139	  const model = explicitMeta?.model || explicitMeta?.modelId ||
140	    (typeof entry.model === 'string' ? entry.model : (entry.model?.id || entry.modelId || entry.model_id || null));
141	
142	  if (!toSpec && !effort && !tier && !model && !explicitMeta) {
143	    return null;
144	  }
145	
146	  return {
147	    fromSpec: explicitMeta?.fromSpec ?? fromSpec,
148	    toSpec: explicitMeta?.toSpec ?? toSpec,
149	    setting: setting || null,
150	    effort: effort || toSpec || null,
151	    tier: tier || null,
152	    model: model || modelToSpec || null,
153	    modelId: modelToSpec ? normalizeModelId(modelToSpec) : null,
154	    modelFromSpec,
155	    modelToSpec,
156	    rawLabel: toSpec || effort || tier || model || ''
157	  };
158	}
