160	/**
161	 * Evaluates step-by-step effort profile resolution and mid-session transitions.
162	 */
163	export function extractEffortTimeline(steps = [], options = {}) {
164	  let currentProfile = { ...EFFORT_PROFILES.STANDARD };
165	  let hasEstablishedTier = false;
166	  let cumTokens = 0;
167	  const effortHistory = [];
168	  const maxTokens = Number(options?.maxTokens) > 0 ? Number(options.maxTokens) : 256000;
169	  const tokensPerCell = Math.max(1, Math.round(maxTokens / 40));
170	
171	  for (let idx = 0; idx < steps.length; idx++) {
172	    const step = steps[idx] || {};
173	    const stepTok = step.inputTokens > 0 && step.outputTokens > 0
174	      ? Math.max(step.outputTokens, Math.round((step.untruncatedLength || 0) / 4))
175	      : (step.outputTokens || Math.round((step.untruncatedLength || 0) / 4) || 1000);
176	    const estBlock = Math.min(39, Math.max(0, Math.floor(cumTokens / tokensPerCell)));
177	    cumTokens += stepTok;
178	
179	    const meta = step.turnMetadata || extractTurnEffortMetadata(step);
180	    if (!meta) continue;
181	
182	    const hasExplicitFrom = meta.fromSpec && !/^none$/i.test(String(meta.fromSpec).trim());
183	    if (hasExplicitFrom) {
184	      const fromProf = resolveEffortProfile(meta.fromSpec);
185	      const toProf = resolveEffortProfile(meta);
186	      const effectiveFrom = hasEstablishedTier ? currentProfile : fromProf;
187	      if (toProf.tier !== effectiveFrom.tier) {
188	        effortHistory.push({
189	          turnIndex: idx,
190	          stepNumber: step.stepIndex ?? idx,
191	          blockIndex: estBlock,
192	          fromTier: effectiveFrom.tier,
193	          toTier: toProf.tier,
194	          fromLabel: effectiveFrom.shortLabel || effectiveFrom.label,
195	          toLabel: toProf.shortLabel || toProf.label,
196	          timestamp: step.createdAt || step.timestamp || null
197	        });
198	      }
199	      currentProfile = toProf;
200	      hasEstablishedTier = true;
201	      continue;
202	    }
203	
204	    if (idx === 0 && !hasEstablishedTier) {
205	      currentProfile = resolveEffortProfile(meta);
206	      hasEstablishedTier = true;
207	      continue;
208	    }
209	
210	    const nextProfile = resolveEffortProfile(meta);
211	    if (nextProfile.tier !== currentProfile.tier) {
212	      effortHistory.push({
213	        turnIndex: idx,
214	        stepNumber: step.stepIndex ?? idx,
215	        blockIndex: estBlock,
216	        fromTier: currentProfile.tier,
217	        toTier: nextProfile.tier,
218	        fromLabel: currentProfile.shortLabel || currentProfile.label,
219	        toLabel: nextProfile.shortLabel || nextProfile.label,
220	        timestamp: step.createdAt || step.timestamp || null
221	      });
222	      currentProfile = nextProfile;
223	    }
224	    hasEstablishedTier = true;
225	  }
226	
227	  return {
228	    activeEffortProfile: currentProfile,
229	    effortHistory
230	  };
231	}
232	
233	/**
234	 * 4-Tier Untruncated Log Resolver
235	 * Tier 1: transcript_full.jsonl
236	 * Tier 2: chunks/transcript_full/*.jsonl
237	 * Tier 3: transcript.jsonl + steps/<idx>/output.txt hydration
238	 * Tier 4: chunks/transcript/*.jsonl
239	 */
240	export function resolveSessionLogs(sessionDir) {
241	  if (!sessionDir || typeof sessionDir !== 'string') return null;
242	
243	  // Support direct file paths for Claude Code (.jsonl) and Cursor (state.vscdb)
244	  try {
245	    if (fs.existsSync(sessionDir) && fs.statSync(sessionDir).isFile()) {
246	      if (sessionDir.toLowerCase().endsWith('.vscdb')) {
247	        return { tier: 1, type: 'cursor-vscdb', path: sessionDir };
248	      }
249	      if (sessionDir.toLowerCase().endsWith('.jsonl')) {
250	        return { tier: 1, type: 'claude-jsonl', path: sessionDir };
251	      }
252	    }
253	  } catch {}
254	
255	  const vscdbCandidate = path.join(sessionDir, 'state.vscdb');
256	  if (fs.existsSync(vscdbCandidate)) {
257	    return { tier: 1, type: 'cursor-vscdb', path: vscdbCandidate };
258	  }
259	
260	  const logsDir = path.join(sessionDir, '.system_generated', 'logs');
261	  const stepsDir = path.join(sessionDir, '.system_generated', 'steps');
262	
263	  // Tier 1
264	  const t1 = path.join(logsDir, 'transcript_full.jsonl');
265	  if (fs.existsSync(t1) && fs.statSync(t1).size > 0) {
266	    return { tier: 1, type: 'single', path: t1 };
267	  }
268	
269	  // Tier 2
270	  const t2Dir = path.join(logsDir, 'chunks', 'transcript_full');
271	  if (fs.existsSync(t2Dir)) {
272	    const chunkFiles = fs.readdirSync(t2Dir)
273	      .filter(f => f.endsWith('.jsonl'))
274	      .sort((a, b) => {
275	        const numA = parseInt(a.replace(/\D/g, '') || '0', 10);
276	        const numB = parseInt(b.replace(/\D/g, '') || '0', 10);
277	        return numA - numB;
278	      })
279	      .map(f => path.join(t2Dir, f));
280	    if (chunkFiles.length > 0) {
281	      return { tier: 2, type: 'chunks', paths: chunkFiles };
282	    }
283	  }
284	
285	  // Tier 3
286	  const t3 = path.join(logsDir, 'transcript.jsonl');
287	  if (fs.existsSync(t3) && fs.statSync(t3).size > 0) {
288	    return { tier: 3, type: 'hydrated', path: t3, stepsDir };
289	  }
290	
291	  // Tier 4
292	  const t4Dir = path.join(logsDir, 'chunks', 'transcript');
293	  if (fs.existsSync(t4Dir)) {
294	    const chunkFiles = fs.readdirSync(t4Dir)
295	      .filter(f => f.endsWith('.jsonl'))
296	      .sort((a, b) => {
297	        const numA = parseInt(a.replace(/\D/g, '') || '0', 10);
298	        const numB = parseInt(b.replace(/\D/g, '') || '0', 10);
299	        return numA - numB;
300	      })
301	      .map(f => path.join(t4Dir, f));
302	    if (chunkFiles.length > 0) {
303	      return { tier: 4, type: 'chunks', paths: chunkFiles };
304	    }
305	  }
306	
307	  return null;
308	}
309	
310	/**
311	 * Parses raw JSONL lines into structured step records.
312	 * Hydrates steps/<idx>/output.txt when tier is 3 and truncated_fields is present.
313	 */
314	export function parseRawJsonl(content, { tier = 1, stepsDir = null, withHealth = false } = {}) {
315	  const lines = content.split(/\r?\n/).filter(line => line.trim().length > 0);
316	  const steps = [];
317	  let malformedLines = 0;
318	  let unknownShapeLines = 0;
319	
320	  for (const line of lines) {
321	    let entry;
322	    try {
323	      entry = JSON.parse(line);
324	    } catch {
325	      malformedLines++;
326	      continue;
327	    }
328	
329	    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
330	      malformedLines++;
331	      continue;
332	    }
333	
334	    // Check recognizable Antigravity/Agent log shape
335	    const hasIdx = entry.step_index !== undefined || entry.stepIndex !== undefined;
336	    const hasType = typeof entry.type === 'string' || entry.step_type !== undefined || entry.stepType !== undefined;
337	    const hasContent = entry.content !== undefined;
338	    const hasRole = typeof entry.role === 'string';
339	    const hasCalls = Array.isArray(entry.tool_calls) || Array.isArray(entry.toolCalls);
340	    if (!hasIdx && !hasType && !hasContent && !hasRole && !hasCalls) {
341	      unknownShapeLines++;
342	      continue;
343	    }
344	
345	    try {
346	      const stepIdx = entry.step_index ?? entry.stepIndex ?? steps.length;
347	      let rawContent = entry.content || '';
348	      let isTruncated = Array.isArray(entry.truncated_fields) && entry.truncated_fields.length > 0;
349	
350	      // Tier 3 Hydration check
351	      if (isTruncated && stepsDir) {
352	        const outputTxtPath = path.join(stepsDir, String(stepIdx), 'output.txt');
353	        if (fs.existsSync(outputTxtPath)) {
354	          try {
355	            rawContent = fs.readFileSync(outputTxtPath, 'utf8');
356	            isTruncated = false;
357	          } catch {
358	            // retain rawContent
359	          }
360	        }
361	      }
362	
363	      const turnMetadata = extractTurnEffortMetadata({ ...entry, content: rawContent });
364	      const usage = entry.usage || entry.token_usage || {};
365	      const cacheReadTokens = Number(
366	        entry.cache_read_input_tokens ??
367	        entry.cacheReadInputTokens ??
368	        usage.cache_read_input_tokens ??
369	        usage.cached_content_token_count ??
370	        0
371	      );
372	      const cacheCreationTokens = Number(
373	        entry.cache_creation_input_tokens ??
374	        entry.cacheCreationInputTokens ??
375	        usage.cache_creation_input_tokens ??
376	        0
377	      );
378	      const thinkingTokens = Number(
379	        entry.thinking_tokens ??
380	        entry.thinkingTokens ??
381	        usage.thinking_tokens ??
382	        usage.thoughts_token_count ??
383	        (entry.thinking ? Math.ceil(String(entry.thinking).length / 4) : 0)
384	      );
385	      const rawSubagentId = entry.subagent_id || entry.subagentId || entry.agent_id || entry.agentId || null;
386	      const agentId = rawSubagentId && rawSubagentId !== 'parent' && rawSubagentId !== 'main'
387	        ? (String(rawSubagentId).startsWith('child:') ? String(rawSubagentId) : `child:${rawSubagentId}`)
388	        : 'parent';
389	
390	      const rawStepType = entry.step_type ?? entry.stepType ?? null;
391	      const isCortexCheckpoint =
392	        Number(rawStepType) === 23 ||
393	        rawStepType === 'CORTEX_STEP_TYPE_CHECKPOINT' ||
394	        entry.type === 'CORTEX_STEP_TYPE_CHECKPOINT' ||
395	        entry.type === 'CHECKPOINT';
396	
397	      steps.push({
398	        stepIndex: stepIdx,
399	        agentId,
400	        source: entry.source || 'MODEL',
401	        type: isCortexCheckpoint ? 'CHECKPOINT' : (entry.type || 'PLANNER_RESPONSE'),
402	        ...(rawStepType !== null ? { stepType: rawStepType, step_type: rawStepType } : (isCortexCheckpoint ? { stepType: 23, step_type: 23 } : {})),
403	        status: entry.status || 'DONE',
404	        createdAt: entry.created_at || entry.createdAt || entry.timestamp || null,
405	        toolCalls: entry.tool_calls || entry.toolCalls || [],
406	        content: rawContent,
407	        inputTokens: entry.input_tokens || entry.inputTokens || usage.input_tokens || 0,
408	        outputTokens: entry.output_tokens || entry.outputTokens || usage.output_tokens || 0,
409	        cacheReadTokens,
410	        cacheCreationTokens,
411	        thinkingTokens,
412	        untruncatedLength: rawContent.length,
413	        isTruncated,
414	        ...(turnMetadata ? { turnMetadata } : {})
415	      });
416	    } catch {
417	      malformedLines++;
418	    }
419	  }
420	
421	  const totalLines = lines.length;
422	  const parsedLines = steps.length;
423	  let confidence = 'HIGH';
424	  if (totalLines > 0) {
425	    const badFraction = (malformedLines + unknownShapeLines) / totalLines;
426	    if (parsedLines === 0 || badFraction > 0.15) {
427	      confidence = 'LOW';
428	    } else if (badFraction > 0.02) {
429	      confidence = 'DEGRADED';
430	    }
431	  }
432	
433	  const health = {
434	    totalLines,
435	    parsedLines,
436	    malformedLines,
437	    unknownShapeLines,
438	    confidence
439	  };
440	
441	  Object.defineProperty(steps, 'health', {
442	    value: health,
443	    enumerable: false,
444	    writable: true,
445	    configurable: true
446	  });
447	
448	  if (withHealth) {
449	    return { steps, health };
450	  }
451	
452	  return steps;
453	}
