455	/**
456	 * Helper to get the real last-activity timestamp of a session folder on Windows
457	 * (checks transcript logs inside .system_generated/logs rather than just folder mtime)
458	 */
459	function getRealSessionMtimeMs(sessionDir) {
460	  let maxMtime = 0;
461	  try {
462	    maxMtime = fs.statSync(sessionDir).mtimeMs;
463	  } catch {
464	    return 0;
465	  }
466	  const candidates = [
467	    path.join(sessionDir, '.system_generated', 'logs', 'transcript_full.jsonl'),
468	    path.join(sessionDir, '.system_generated', 'logs', 'transcript.jsonl')
469	  ];
470	  for (const c of candidates) {
471	    try {
472	      if (fs.existsSync(c)) {
473	        const m = fs.statSync(c).mtimeMs;
474	        if (m > maxMtime) maxMtime = m;
475	      }
476	    } catch {}
477	  }
478	  return maxMtime;
479	}
