481	/**
482	 * Discovers Claude Code sessions under ~/.claude/projects/<project>/<sid>.jsonl
483	 * Direct calls work as an explicit adapter; automatic discovery callers pass options.
484	 */
485	export function discoverClaudeCodeSessions(homeDir = getHomeDir(), options = { includeCrossHost: true }) {
486	  const projectsDir = getClaudeCodeProjectsDir(homeDir, options);
487	  if (!projectsDir || !fs.existsSync(projectsDir)) return [];
488	  const sessions = [];
489	  const inspectJsonlFile = (fullPath, projectSlug = '') => {
490	    try {
491	      const stat = fs.statSync(fullPath);
492	      if (!stat.isFile() || stat.size === 0) return;
493	      const base = path.basename(fullPath);
494	      if (!base.endsWith('.jsonl') || base.startsWith('.')) return;
495	      const sessionId = base.replace(/\.jsonl$/i, '');
496	      sessions.push({
497	        storeName: 'claude-code',
498	        surface: 'claude-code',
499	        surfaceTag: '[Claude]',
500	        sessionDir: fullPath,
501	        filePath: fullPath,
502	        sessionId,
503	        projectSlug,
504	        mtimeMs: stat.mtimeMs
505	      });
506	    } catch {}
507	  };
508	
509	  try {
510	    const entries = fs.readdirSync(projectsDir, { withFileTypes: true });
511	    for (const entry of entries) {
512	      const full = path.join(projectsDir, entry.name);
513	      if (entry.isFile() && entry.name.endsWith('.jsonl')) {
514	        inspectJsonlFile(full, '');
515	      } else if (entry.isDirectory()) {
516	        try {
517	          const children = fs.readdirSync(full);
518	          for (const child of children) {
519	            if (child.endsWith('.jsonl')) {
520	              inspectJsonlFile(path.join(full, child), entry.name);
521	            }
522	          }
523	        } catch {}
524	      }
525	    }
526	  } catch {}
527	
528	  return sessions.sort((a, b) => b.mtimeMs - a.mtimeMs);
529	}
