531	/**
532	 * Discovers Cursor IDE sessions under workspaceStorage/<hash>/state.vscdb in strict read-only mode.
533	 * Direct calls work as an explicit adapter; automatic discovery callers pass options.
534	 */
535	export function discoverCursorSessions(homeDir = getHomeDir(), DatabaseSyncClass = null, options = { includeCrossHost: true }) {
536	  const storageDirs = getCursorWorkspaceStorageDirs(homeDir, options);
537	  if (storageDirs.length === 0) return [];
538	  const DbCtor = DatabaseSyncClass || getSqliteDatabaseSync();
539	  const sessions = [];
540	
541	  for (const storageRoot of storageDirs) {
542	    let entries = [];
543	    try {
544	      entries = fs.readdirSync(storageRoot, { withFileTypes: true });
545	    } catch {
546	      continue;
547	    }
548	    for (const entry of entries) {
549	      if (!entry.isDirectory()) continue;
550	      const wsDir = path.join(storageRoot, entry.name);
551	      const vscdbPath = path.join(wsDir, 'state.vscdb');
552	      if (!fs.existsSync(vscdbPath)) continue;
553	      try {
554	        const stat = fs.statSync(vscdbPath);
555	        if (!stat.isFile() || stat.size === 0) continue;
556	        let composerId = null;
557	        let title = '';
558	        let bubbleCount = 0;
559	        let workspaceUri = '';
560	
561	        const wsJsonPath = path.join(wsDir, 'workspace.json');
562	        if (fs.existsSync(wsJsonPath)) {
563	          try {
