355	 * churning 5m sessions require `readToWriteRatio >= 1.39` (`1.25 / 0.90`) for sustained healthy ROI.
356	 */
357	export function computeCacheRoi({
358	  cacheReadTokens = 0,
359	  write5mTokens = 0,
360	  write1hTokens = 0,
361	  cacheCreationTokens = 0,
362	  uncachedInputTokens = 0,
363	  outputTokens = 0,
364	  modelId = 'claude-sonnet-5-5',
365	  eventTimestampUtc = null,
366	  serviceTier = 'standard',
367	  totalPromptTokens = null
368	} = {}) {
369	  const readTok = Math.max(0, Number(cacheReadTokens) || 0);
370	  const rawW5m = Math.max(0, Number(write5mTokens) || 0);
371	  const rawW1h = Math.max(0, Number(write1hTokens) || 0);
372	  const rawCreate = Math.max(0, Number(cacheCreationTokens) || 0);
373	  const uncachedTok = Math.max(0, Number(uncachedInputTokens) || 0);
374	  const outTok = Math.max(0, Number(outputTokens) || 0);
375	
376	  const effWrite1h = rawW1h;
377	  const effWrite5m = (rawW5m > 0 || rawW1h > 0) ? rawW5m : rawCreate;
378	  const totalWriteTokens = effWrite5m + effWrite1h;
379	  const promptEnvelope = totalPromptTokens !== null && totalPromptTokens !== undefined
380	    ? Math.max(0, Number(totalPromptTokens) || 0)
381	    : (uncachedTok + readTok + totalWriteTokens);
382	
383	  const rates = resolveModelRates(modelId, eventTimestampUtc, serviceTier, {
384	    totalPromptTokens: promptEnvelope
385	  });
386	
387	  const write5mRate = rates.write5m > 0 ? rates.write5m : rates.input;
388	  const write1hRate = rates.write1h > 0 ? rates.write1h : rates.input;
389	  const hasExplicitWriteSurcharge = write5mRate > rates.input || write1hRate > rates.input;
390	
391	  const writePremiumUsd =
392	    ((effWrite5m / 1_000_000) * Math.max(0, write5mRate - rates.input)) +
393	    ((effWrite1h / 1_000_000) * Math.max(0, write1hRate - rates.input));
394	  const readDiscountSavingsUsd =
395	    (readTok / 1_000_000) * Math.max(0, rates.input - rates.cachedRead);
396	  const netCacheSavingsUsd = Number((readDiscountSavingsUsd - writePremiumUsd).toFixed(6));
397	
398	  const actualCacheCostUsd = Number((
399	    ((uncachedTok / 1_000_000) * rates.input) +
400	    ((effWrite5m / 1_000_000) * write5mRate) +
401	    ((effWrite1h / 1_000_000) * write1hRate) +
402	    ((readTok / 1_000_000) * rates.cachedRead) +
403	    ((outTok / 1_000_000) * rates.output)
404	  ).toFixed(6));
405	
406	  const uncachedBaselineUsd = Number((
407	    (((uncachedTok + totalWriteTokens + readTok) / 1_000_000) * rates.input) +
408	    ((outTok / 1_000_000) * rates.output)
409	  ).toFixed(6));
410	
411	  const readToWriteRatio = totalWriteTokens > 0
412	    ? Number((readTok / totalWriteTokens).toFixed(4))
413	    : (readTok > 0 ? null : 0);
414	
415	  const avgWriteRate = totalWriteTokens > 0
416	    ? ((effWrite5m * write5mRate + effWrite1h * write1hRate) / totalWriteTokens)
417	    : write5mRate;
418	  const singleWriteBreakEvenRatio = (avgWriteRate > rates.input && rates.input > rates.cachedRead)
419	    ? Number(((avgWriteRate - rates.input) / (rates.input - rates.cachedRead)).toFixed(4))
420	    : 0;
421	
422	  const belowSessionRoiThreshold = totalWriteTokens > 0 &&
423	    (readTok / totalWriteTokens) < SESSION_5M_READ_TO_WRITE_MIN_ROI_RATIO;
424	  const isNetUsdNegative = netCacheSavingsUsd < 0;
425	  const isNegativeCacheRoi = isNetUsdNegative || (hasExplicitWriteSurcharge && belowSessionRoiThreshold);
426	
427	  return {
428	    rates: {
429	      input: rates.input,
430	      output: rates.output,
431	      write5m: rates.write5m,
432	      write1h: rates.write1h,
433	      cachedRead: rates.cachedRead,
434	      isAbovePromptCliff: Boolean(rates.isAbovePromptCliff)
435	    },
436	    cacheReadTokens: readTok,
437	    write5mTokens: effWrite5m,
438	    write1hTokens: effWrite1h,
439	    totalWriteTokens,
440	    readToWriteRatio,
441	    singleWriteBreakEvenRatio,
442	    minSessionReadToWriteRatio: SESSION_5M_READ_TO_WRITE_MIN_ROI_RATIO,
443	    belowSessionRoiThreshold,
444	    writePremiumUsd: Number(writePremiumUsd.toFixed(6)),
445	    readDiscountSavingsUsd: Number(readDiscountSavingsUsd.toFixed(6)),
446	    netCacheSavingsUsd,
447	    actualCacheCostUsd,
448	    uncachedBaselineUsd,
449	    isNetUsdNegative,
450	    isNegativeCacheRoi
451	  };
452	}
