454	/**
455	 * Formats a token count into a compact string ("140k", "3.7k").
456	 */
457	export function formatK(num) {
458	  const n = Number(num || 0);
459	  if (n <= 0) return '0k';
460	  if (n < 1000) return `${Math.round(n)}`;
461	  const k = n / 1000;
462	  return k >= 10 ? `${Math.round(k)}k` : `${parseFloat(k.toFixed(1))}k`;
463	}
