465	/**
466	 * Prefix Bust label. A known model-switch cause gets a plain-language amber label; an unknown
467	 * cause keeps the legacy label.
468	 */
469	export function formatPrefixBustLabel(cause = null) {
470	  if (cause && cause.cause === 'auto_router_thrash') {
471	    return cause.badgeText || `\u26A0\uFE0F Router Thrash: ${cause.switchCount} model hops`;
472	  }
473	  if (cause && cause.cause === 'model_switch' && cause.to) {
474	    return `Last turn: cache miss (model switch \u2192 ${humanizeModelLabel(cause.to)})`;
475	  }
476	  if (cause && cause.cause === 'warm_pool_busted') {
477	    return cause.reason === 'RULE_FILE_DRIFT'
478	      ? '\u26A0\uFE0F Prefix Bust (system_message / config drift)'
479	      : '\u26A0\uFE0F Prefix Bust (history mutation)';
480	  }
481	  return OVERAGE_ALERT_MESSAGES.PREFIX_BUST_LABEL;
482	}
