627	/**
628	 * Pure sliding-window (last 5 turns) Auto-Router Thrash and Model Switch detector.
629	 * Scopes switch counting strictly within the same `(session_id, agent_id)` stream so multi-agent
630	 * `/swarm` turns never trigger false-positive thrash alerts across distinct agents.
631	 */
632	export function detectRouterThrash(recentTurns = [], isAutoMode = false, {
633	  sessionId = 'default_session',
634	  totalTokens = 0,
635	  reclaimableTokens = 0,
636	  standbyCache = null,
637	  lastSwitchEvent = null
638	} = {}) {
639	  if (!Array.isArray(recentTurns) || recentTurns.length === 0) {
640	    return {
641	      detected: false,
642	      thrashDetected: false,
643	      state: 'HEALTHY',
644	      severity: 'none',
645	      isAutoMode,
646	      windowTurns: 0,
647	      switchCount: 0,
648	      thrashUncachedTokens: 0,
649	      modelSequenceString: '',
650	      modelsInvolved: [],
651	      badgeText: '',
652	      tooltip: '',
653	      standbyNote: '',
654	      preSwitchCompactionAdvice: ''
655	    };
656	  }
657	
658	  const windowTurns = recentTurns.slice(-5);
659	  let switchCount = 0;
660	  let thrashUncachedTokens = 0;
661	  const lastModelByStream = new Map();
662	
663	  for (let i = 0; i < windowTurns.length; i++) {
664	    const curr = windowTurns[i];
665	    const tSid = String(curr.session_id || curr.sessionId || sessionId || 'default_session');
666	    const aId = resolveStepAgentId(curr);
667	    const streamKey = formatAgentStreamKey(tSid, aId);
668	    const currM = normalizeModelId(curr.active_model_id || curr.modelId || curr.model || 'gemini-4-argon');
669	    const prevM = lastModelByStream.get(streamKey);
670	    if (prevM && currM !== prevM) {
671	      switchCount++;
672	      const uncached = Number(curr.inputTokens || 0) || Number(curr.uncachedInputTokens || 0) || Math.max(0, Number(curr.totalTokens || 0) - Number(curr.cacheReadTokens || 0));
673	      thrashUncachedTokens += uncached;
674	    }
675	    lastModelByStream.set(streamKey, currM);
676	  }
677	
678	  if (thrashUncachedTokens === 0 && switchCount > 0 && totalTokens > 0) {
679	    thrashUncachedTokens = totalTokens * switchCount;
680	  }
681	
682	  const seqShort = [];
683	  for (const t of windowTurns) {
684	    const sName = resolveModelShortName(t.modelRaw || t.model || t.modelId);
685	    if (seqShort.length === 0 || seqShort[seqShort.length - 1] !== sName) {
686	      seqShort.push(sName);
687	    }
688	  }
689	  const modelSequenceString = seqShort.join(' \u2192 ');
690	  const modelsInvolved = [...new Set(seqShort)];
691	
692	  const lastTurn = windowTurns[windowTurns.length - 1];
693	  const lastTurnAgentId = lastTurn ? resolveStepAgentId(lastTurn) : 'primary';
694	  const lastTurnSid = lastTurn ? String(lastTurn.session_id || lastTurn.sessionId || sessionId || 'default_session') : sessionId;
695	  const lastStreamKey = formatAgentStreamKey(lastTurnSid, lastTurnAgentId);
696	  let prevTurnSameStream = null;
697	  for (let i = windowTurns.length - 2; i >= 0; i--) {
698	    const candidate = windowTurns[i];
699	    const cSid = String(candidate.session_id || candidate.sessionId || sessionId || 'default_session');
700	    const cAid = resolveStepAgentId(candidate);
701	    if (formatAgentStreamKey(cSid, cAid) === lastStreamKey) {
702	      prevTurnSameStream = candidate;
703	      break;
704	    }
705	  }
706	  const isCurrentTurnSwitch = Boolean(
707	    lastTurn && prevTurnSameStream &&
708	    normalizeModelId(lastTurn.active_model_id || lastTurn.modelId || lastTurn.model || '') !==
709	      normalizeModelId(prevTurnSameStream.active_model_id || prevTurnSameStream.modelId || prevTurnSameStream.model || '')
710	  );
711	  const currentShortName = lastTurn ? resolveModelShortName(lastTurn.modelRaw || lastTurn.model || lastTurn.modelId) : 'Model';
712	  const currentDisplayName = lastTurn ? resolveModelPoolDisplayName(lastTurn.modelId || lastTurn.model) : 'Model';
713	
714	  const totalPrompt = Number(lastTurn?.cacheReadTokens || 0) + Number(lastTurn?.cacheCreationTokens || 0) + Number(lastTurn?.inputTokens || 0);
715	  const cacheHitPct = totalPrompt > 0 ? (Number(lastTurn?.cacheReadTokens || 0) / totalPrompt) * 100 : 0;
716	
717	  // Case A: Router Thrashing (2+ switches in 5 turns in [Auto] mode)
718	  if (switchCount >= 2 && isAutoMode) {
719	    const badgeText = `\u26A0\uFE0F Router Thrash: ${switchCount} model hops (${formatK(thrashUncachedTokens)} uncached)`;
720	    const tooltip = `Auto-routing is bouncing between models (${modelSequenceString}), paying full uncached prefill cost on every hop. Pin a single model or run /compact.`;
721	    return {
722	      detected: true,
723	      thrashDetected: true,
724	      state: 'AUTO_ROUTER_THRASH',
725	      severity: 'warn',
726	      isAutoMode,
727	      windowTurns: windowTurns.length,
728	      switchCount,
729	      thrashUncachedTokens,
730	      modelSequenceString,
731	      modelsInvolved,
732	      currentShortName,
733	      currentDisplayName,
734	      badgeText,
735	      tooltip,
736	      standbyNote: standbyCache ? `(${standbyCache.modelName} cache still warm: ${standbyCache.remainingTtl}s left)` : '',
737	      preSwitchCompactionAdvice: ''
738	    };
739	  }
740	
741	  // Case B: Single Model Switch / Cold Start
742	  const lastTurnMissedCache = Number(lastTurn?.cacheReadTokens || 0) === 0;
743	  const isLastTurnSwitchEvent = Boolean(
744	    lastSwitchEvent && lastTurn && (lastTurn.stepIndex ?? (recentTurns.length - 1)) === lastSwitchEvent.turnIndex
745	  );
746	  if ((isCurrentTurnSwitch || isLastTurnSwitchEvent) && lastTurnMissedCache) {
747	    const severity = (isAutoMode && totalTokens >= 100000) ? 'warn' : 'info';
748	    const badgeText = `Last turn: cache miss (model switch \u2192 ${currentShortName})`;
749	    const standbyNote = standbyCache ? `(${standbyCache.modelName} cache still warm: ${standbyCache.remainingTtl}s left)` : '';
750	    const tooltip = standbyCache
751	      ? `Last turn missed prompt cache due to model switch \u2192 ${currentDisplayName}. (${standbyCache.modelName} cache still warm: ${standbyCache.remainingTtl}s left)`
752	      : `Last turn missed prompt cache due to model switch \u2192 ${currentDisplayName}.`;
753	
754	    let preSwitchCompactionAdvice = '';
755	    if (reclaimableTokens >= 40000) {
756	      preSwitchCompactionAdvice = `Switching to ${currentShortName} forced a full ${formatK(totalTokens)} uncached rebuild (including ${formatK(reclaimableTokens)} of reclaimable waste). Tip: Run /compact before switching models so the incoming model only warms up active signal.`;
757	    }
758	
759	    return {
760	      detected: false,
761	      thrashDetected: false,
762	      state: 'MODEL_SWITCH_COLD_START',
763	      severity,
764	      isAutoMode,
765	      windowTurns: windowTurns.length,
766	      switchCount,
767	      thrashUncachedTokens,
768	      modelSequenceString,
769	      modelsInvolved,
770	      currentShortName,
771	      currentDisplayName,
772	      badgeText,
773	      tooltip,
774	      standbyNote,
775	      preSwitchCompactionAdvice
776	    };
777	  }
778	
779	  // Case C: One-Turn Decay to Healthy
780	  // When session stays on the same model and achieves cacheHit > 50% (or positive cacheReadTokens)
781	  if (!isCurrentTurnSwitch && (cacheHitPct > 50 || Number(lastTurn?.cacheReadTokens || 0) > 0)) {
782	    return {
783	      detected: false,
784	      thrashDetected: false,
785	      state: 'HEALTHY',
786	      severity: 'none',
787	      isAutoMode,
788	      windowTurns: windowTurns.length,
789	      switchCount: 0,
790	      thrashUncachedTokens: 0,
791	      modelSequenceString,
792	      modelsInvolved,
793	      currentShortName,
794	      currentDisplayName,
795	      badgeText: '',
796	      tooltip: '',
797	      standbyNote: '',
798	      preSwitchCompactionAdvice: ''
799	    };
800	  }
801	
802	  return {
803	    detected: false,
804	    thrashDetected: false,
805	    state: 'HEALTHY',
806	    severity: 'none',
807	    isAutoMode,
808	    windowTurns: windowTurns.length,
809	    switchCount,
810	    thrashUncachedTokens,
811	    modelSequenceString,
812	    modelsInvolved,
813	    currentShortName,
814	    currentDisplayName,
815	    badgeText: '',
816	    tooltip: '',
817	    standbyNote: '',
818	    preSwitchCompactionAdvice: ''
819	  };
820	}
