188	export function formatResetCountdown(resetSeconds) {
189	  const sec = Math.max(0, Math.round(Number(resetSeconds || 0)));
190	  if (sec <= 0) return '0m';
191	  const totalMinutes = Math.max(1, Math.floor(sec / 60));
192	  const days = Math.floor(totalMinutes / (60 * 24));
193	  if (days >= 1) {
194	    const remHours = Math.floor((totalMinutes % (60 * 24)) / 60);
195	    return `${days}d ${remHours}h`;
196	  }
197	  const hours = Math.floor(totalMinutes / 60);
198	  const mins = totalMinutes % 60;
199	  if (hours >= 1) {
200	    return `${hours}h ${mins}m`;
201	  }
202	  return `${mins}m`;
203	}
