260	/**
261	 * Detects whether a step or its immediately preceding step contained an explicit
262	 * prefix-invalidating event (<USER_SETTINGS_CHANGE>, <system_message>, model/effort
263	 * switch, or an edit to AGENTS.md / .agents/rules/ / mcp_config.json).
264	 */
265	export function hasExplicitPrefixMutation(step = {}, prevStep = null) {
266	  // Only genuine user/system turns can carry a settings change or system message.
267	  // Tool output, code views, and planner text that merely *mention* the tags are ignored.
268	  const isUserOrSystemStep = (st) => {
269	    const t = String(st?.type || '').toUpperCase();
270	    return t === 'USER_INPUT' || t.startsWith('SYSTEM');
271	  };
272	  const checkText = (st) => {
273	    if (!isUserOrSystemStep(st)) return false;
274	    const txt = String(st?.content || '');
275	    return /<USER_SETTINGS_CHANGE>|<system_message>/i.test(txt);
276	  };
277	  const checkToolEdit = (st) => {
278	    for (const c of (st?.toolCalls || [])) {
279	      if (!/write|edit|replace|create/i.test(String(c?.name || ''))) continue;
280	      const p = String(c?.args?.Path || c?.args?.path || c?.args?.TargetFile || c?.args?.AbsolutePath || '');
281	      if (/(^|[\\/])(AGENTS\.md|mcp_config\.json)$|[\\/]\.agents[\\/]rules[\\/]/i.test(p)) {
282	        return true;
283	      }
284	    }
285	    return false;
286	  };
287	  if (checkText(step) || checkToolEdit(step)) return true;
288	  if (prevStep && (checkText(prevStep) || checkToolEdit(prevStep))) return true;
289	  if (prevStep?.model && step?.model && prevStep.model !== step.model) return true;
290	  if (prevStep?.effort && step?.effort && prevStep.effort !== step.effort) return true;
291	  return false;
292	}
