294	/**
295	 * attributes a prefix bust to a model switch when the busting step (or the step
296	 * just before it) is a USER_INPUT carrying a `Model Selection` settings change, or when
297	 * consecutive steps carry different model ids.
298	 */
299	export function detectModelSwitchCause(step = {}, prevStep = null) {
300	  for (const st of [step, prevStep]) {
301	    if (!st || String(st.type || '').toUpperCase() !== 'USER_INPUT') continue;
302	    const changes = parseSettingsChanges(String(st.content || '')).filter(c => /model selection/i.test(c.setting));
303	    if (changes.length > 0) {
304	      const last = changes[changes.length - 1];
305	      return { cause: 'model_switch', from: last.from, to: last.to };
306	    }
307	  }
308	  if (prevStep?.model && step?.model && prevStep.model !== step.model) {
309	    return { cause: 'model_switch', from: prevStep.model, to: step.model };
310	  }
311	  return null;
312	}
