484	/**
485	 * Pure, deterministic tracker for per-model and composite (`${session_id}::${agent_id}::${model_id}`) KV cache pools.
486	 * Scopes model-switch detection strictly within the same `(session_id, agent_id)` stream so parallel
487	 * `/swarm` and `/teamwork` agents never cross-contaminate each other's cache baselines.
488	 */
489	export function trackModelCachePools(turns = [], {
490	  sessionId = 'default_session',
491	  nowMs = Date.now(),
492	  prefixDiff = null
493	} = {}) {
494	  const modelCachePools = new Map();
495	  const compositeCachePools = new Map();
496	  const prevTurnByStream = new Map();
497	  let standbyCache = null;
498	  let lastSwitchEvent = null;
499	
500	  for (let i = 0; i < turns.length; i++) {
501	    const turn = turns[i];
502	    const turnSessionId = String(turn.session_id || turn.sessionId || sessionId || 'default_session');
503	    const agentId = resolveStepAgentId(turn);
504	    const streamKey = formatAgentStreamKey(turnSessionId, agentId);
505	    const prevTurn = prevTurnByStream.get(streamKey) || null;
506	
507	    const mId = normalizeModelId(turn.active_model_id || turn.modelId || turn.model || 'gemini-4-argon');
508	    const compositeKey = formatAgentCacheKey(turnSessionId, agentId, mId);
509	    const shortName = resolveModelShortName(turn.modelRaw || turn.model || mId);
510	    const displayName = resolveModelPoolDisplayName(mId);
511	    const ts = turn.timestampMs || (turn.createdAt ? Date.parse(turn.createdAt) : nowMs);
512	    const ttlWindow = Number(turn.ttlSeconds || QUOTA_CONSTANTS.CACHE_TTL_SECONDS);
513	
514	    const prevMId = prevTurn
515	      ? normalizeModelId(prevTurn.active_model_id || prevTurn.modelId || prevTurn.model || 'gemini-4-argon')
516	      : null;
517	    const prevCompositeKey = prevTurn ? formatAgentCacheKey(turnSessionId, agentId, prevMId) : null;
518	    const isModelSwitch = Boolean(prevTurn && prevMId && prevMId !== mId);
519	
520	    // Update remaining TTL for all existing pools up to this turn
521	    for (const pool of compositeCachePools.values()) {
522	      const elapsedSec = Math.max(0, Math.floor((ts - pool.lastSeenTimestampMs) / 1000));
523	      pool.remainingTtl = Math.max(0, pool.ttlSecondsAtLastTurn - elapsedSec);
524	      pool.isWarm = pool.remainingTtl > 0 && pool.lastCachedTokens > 0;
525	    }
526	    for (const pool of modelCachePools.values()) {
527	      const elapsedSec = Math.max(0, Math.floor((ts - pool.lastSeenTimestampMs) / 1000));
528	      pool.remainingTtl = Math.max(0, pool.ttlSecondsAtLastTurn - elapsedSec);
529	      pool.isWarm = pool.remainingTtl > 0 && pool.lastCachedTokens > 0;
530	    }
531	
532	    if (isModelSwitch) {
533	      const modelA = compositeCachePools.get(prevCompositeKey) || modelCachePools.get(prevMId);
534	      const modelB = compositeCachePools.get(compositeKey);
535	
536	      // Check if Model A still has remainingTtl > 30 and lastCachedTokens > 20000
537	      if (modelA && modelA.remainingTtl > 30 && modelA.lastCachedTokens > 20000) {
538	        standbyCache = {
539	          modelName: modelA.shortName,
540	          remainingTtl: modelA.remainingTtl,
541	          cachedTokens: modelA.lastCachedTokens,
542	          agentId
543	        };
544	      } else {
545	        standbyCache = null;
546	      }
547	
548	      // Check if Model B already had a warm entry in compositeCachePools for this agent that unexpectedly missed
549	      let warmPoolBustedReason = null;
550	      if (modelB && modelB.remainingTtl > 0 && Number(turn.cacheReadTokens || 0) === 0) {
551	        const isRuleDrift = Boolean(turn.explicitMutation || prefixDiff?.mutated);
552	        warmPoolBustedReason = isRuleDrift ? 'RULE_FILE_DRIFT' : 'HISTORY_MUTATION';
553	      }
554	
555	      lastSwitchEvent = {
556	        sessionId: turnSessionId,
557	        agentId,
558	        streamKey,
559	        fromModelId: prevMId,
560	        toModelId: mId,
561	        fromShortName: resolveModelShortName(prevTurn.modelRaw || prevTurn.model || prevMId),
562	        toShortName: shortName,
563	        toDisplayName: displayName,
564	        turnIndex: turn.stepIndex ?? i,
565	        timestampMs: ts,
566	        warmPoolBustedReason,
567	        standbyCache: standbyCache ? { ...standbyCache } : null
568	      };
569	    }
570	
571	    const cachedTokens = turn.cacheReadTokens > 0
572	      ? turn.cacheReadTokens
573	      : (turn.cacheCreationTokens > 0 ? turn.cacheCreationTokens : (turn.cachedTokens || 0));
574	
575	    const existingComposite = compositeCachePools.get(compositeKey);
576	    const poolEntry = {
577	      compositeKey,
578	      sessionId: turnSessionId,
579	      agentId,
580	      modelId: mId,
581	      shortName,
582	      displayName,
583	      lastSeenTurnId: turn.stepIndex ?? i,
584	      lastSeenTimestampMs: ts,
585	      lastCachedTokens: cachedTokens > 0 ? cachedTokens : (existingComposite?.lastCachedTokens || 0),
586	      lastPrefixHash: turn.prefixHash || existingComposite?.lastPrefixHash || '',
587	      ttlSecondsAtLastTurn: ttlWindow,
588	      remainingTtl: ttlWindow,
589	      isWarm: cachedTokens > 0
590	    };
591	    compositeCachePools.set(compositeKey, poolEntry);
592	    modelCachePools.set(mId, { ...poolEntry });
593	    prevTurnByStream.set(streamKey, turn);
594	  }
595	
596	  // Final evaluation of remaining TTL against nowMs
597	  for (const pool of compositeCachePools.values()) {
598	    const elapsedSec = Math.max(0, Math.floor((nowMs - pool.lastSeenTimestampMs) / 1000));
599	    pool.remainingTtl = Math.max(0, pool.ttlSecondsAtLastTurn - elapsedSec);
600	    pool.isWarm = pool.remainingTtl > 0 && pool.lastCachedTokens > 0;
601	  }
602	  for (const pool of modelCachePools.values()) {
603	    const elapsedSec = Math.max(0, Math.floor((nowMs - pool.lastSeenTimestampMs) / 1000));
604	    pool.remainingTtl = Math.max(0, pool.ttlSecondsAtLastTurn - elapsedSec);
605	    pool.isWarm = pool.remainingTtl > 0 && pool.lastCachedTokens > 0;
606	  }
607	
608	  if (standbyCache && lastSwitchEvent) {
609	    const prevKey = formatAgentCacheKey(lastSwitchEvent.sessionId, lastSwitchEvent.agentId, lastSwitchEvent.fromModelId);
610	    const modelA = compositeCachePools.get(prevKey) || modelCachePools.get(lastSwitchEvent.fromModelId);
611	    if (modelA) {
612	      standbyCache.remainingTtl = modelA.remainingTtl;
613	      if (standbyCache.remainingTtl <= 0) {
614	        standbyCache = null;
615	      }
616	    }
617	  }
618	
619	  return {
620	    modelCachePools,
621	    compositeCachePools,
622	    standbyCache,
623	    lastSwitchEvent
624	  };
625	}
