788	      windowTurns: windowTurns.length,
789	      switchCount: 0,
790	      thrashUncachedTokens: 0,
791	      modelSequenceString,
792	      modelsInvolved,
793	      currentShortName,
794	      currentDisplayName,
795	      badgeText: '',
796	      tooltip: '',
797	      standbyNote: '',
798	      preSwitchCompactionAdvice: ''
799	    };
800	  }
